-- 016_creative_catalog.sql -- creative module tables (accounts allowlist + friendly-name catalog).
-- Owner runs on dev + prod. Public mapping data only, no secrets. Never edit after apply; next = 017+.
CREATE SCHEMA IF NOT EXISTS creative;
CREATE TABLE IF NOT EXISTS creative.accounts (name TEXT PRIMARY KEY, username TEXT NOT NULL DEFAULT '', account_id TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, live BOOLEAN NOT NULL DEFAULT FALSE, top_affiliate BOOLEAN NOT NULL DEFAULT FALSE, position INT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NULL);
CREATE TABLE IF NOT EXISTS creative.catalog_campaigns (campaign_id TEXT PRIMARY KEY, label TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', archived BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS creative.catalog_products (product_id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', campaign_id TEXT NOT NULL DEFAULT '', archived BOOLEAN NOT NULL DEFAULT FALSE);
